data = sys.stdin.read().split()
n = int(data[0])
edges = [(int(data[1 + 2 * i]), int(data[2 + 2 * i])) for i in range(n - 1)]

def depth(u, parent):
    best = 0
    for a, b in edges:
        for x, y in ((a, b), (b, a)):
            if x == u and y != parent:
                best = max(best, depth(y, u))
    return best + 1

