def gen(rng):
    def build(n, parents):
        # parents[i] is the parent (an earlier node in construction order) of construction node i+1
        perm = list(range(1, n))
        rng.shuffle(perm)
        label = [0] + perm
        edges = []
        for i in range(1, n):
            a, b = label[parents[i - 1]], label[i]
            if rng.random() < 0.5:
                a, b = b, a
            edges.append((a, b))
        rng.shuffle(edges)
        return str(n) + ('\n' if edges else '') + '\n'.join(f'{a} {b}' for a, b in edges)

    def random_tree(n, maxdepth=10**9):
        depth = [1]
        parents = []
        for i in range(1, n):
            while True:
                p = rng.randrange(i)
                if depth[p] < maxdepth:
                    break
            parents.append(p)
            depth.append(depth[p] + 1)
        return build(n, parents)

    tests = [build(1, []), build(2, [0]), build(3, [0, 1]), build(3, [0, 0]), build(5, [0, 0, 0, 0]), build(6, [0, 1, 2, 3, 4])]
    for n in (4, 6, 8, 10, 14, 20, 25):
        for _ in range(2):
            tests.append(random_tree(n))
    # large: deep path plus bushy rest, star, random, caterpillar
    N = 100000
    parents = list(range(4999))  # a path of 5000 nodes
    depth = list(range(1, 5001))
    for i in range(5000, N):
        while True:
            p = rng.randrange(i)
            if depth[p] < 5000:
                break
        parents.append(p)
        depth.append(depth[p] + 1)
    tests.append(build(N, parents))
    tests.append(build(N, [0] * (N - 1)))
    tests.append(random_tree(N))
    cat = []
    for i in range(1, N):
        cat.append(i - 1 if i < 2500 else rng.randrange(2500))
    tests.append(build(N, cat))
    tests.append(build(5000, list(range(4999))))
    return tests

